// MAIRFM Sleep — landscape bedside adapter with live artwork + volume.
(()=>{
'use strict';
if(window.MAIRSleepLandscapePrototype)return;
const media=window.matchMedia('(orientation: landscape) and (min-width: 700px)');
let enabled=true,lastApplied=false;
const $=id=>document.getElementById(id);
function overlay(){return $('mairSleepOverlay')}
function artworkSrc(){const img=$('artImg');const src=String(img?.currentSrc||img?.src||'').trim();return src||'mair-icon-512.png'}
function ensureStyle(){if($('mairSleepLandscapeExtrasStyle'))return;const s=document.createElement('style');s.id='mairSleepLandscapeExtrasStyle';s.textContent=`@media (orientation:landscape) and (min-width:700px){#mairSleepOverlay.mair-sleep-landscape-v2 .mair-sleep-now::before{display:none!important}#mairSleepOverlay.mair-sleep-landscape-v2 .mair-sleep-now{grid-template-columns:190px minmax(0,1fr)!important}#mairSleepOverlay.mair-sleep-landscape-v2 .mair-sleep-landscape-art{grid-area:now;align-self:center;justify-self:start;width:180px;aspect-ratio:1;object-fit:cover;border-radius:20px;border:1px solid rgba(184,111,255,.22);box-shadow:0 20px 60px rgba(0,0,0,.28),0 0 36px rgba(147,69,231,.14);z-index:3}#mairSleepOverlay.mair-sleep-landscape-v2 .mair-sleep-landscape-volume{grid-area:volume;align-self:center;justify-self:start;width:min(360px,42vw);display:grid;grid-template-columns:auto minmax(120px,1fr) auto;align-items:center;gap:12px;color:#bdb7c7;z-index:3}#mairSleepOverlay.mair-sleep-landscape-v2 .mair-sleep-landscape-volume input{width:100%;accent-color:#984cff}#mairSleepOverlay.mair-sleep-landscape-v2 .mair-sleep-wrap::after{display:none!important}}@media (orientation:landscape) and (min-width:700px) and (max-height:390px){#mairSleepOverlay.mair-sleep-landscape-v2 .mair-sleep-landscape-art{width:136px;border-radius:17px}#mairSleepOverlay.mair-sleep-landscape-v2 .mair-sleep-landscape-volume{width:min(330px,44vw)}}`;document.head.appendChild(s)}
function ensureExtras(){ensureStyle();const node=overlay();const wrap=node?.querySelector('.mair-sleep-wrap');if(!wrap)return;let art=$('mairSleepLandscapeArt');if(!art){art=document.createElement('img');art.id='mairSleepLandscapeArt';art.className='mair-sleep-landscape-art';art.alt='Albumhoes';wrap.appendChild(art)}art.src=artworkSrc();let vol=$('mairSleepLandscapeVolume');if(!vol){vol=document.createElement('label');vol.id='mairSleepLandscapeVolume';vol.className='mair-sleep-landscape-volume';vol.innerHTML='<span>🔊</span><input id="mairSleepLandscapeVolumeRange" type="range" min="0" max="100" value="55" aria-label="Volume"><output id="mairSleepLandscapeVolumeValue">55</output>';wrap.appendChild(vol);const range=$('mairSleepLandscapeVolumeRange'),out=$('mairSleepLandscapeVolumeValue');range?.addEventListener('input',()=>{const n=Math.max(0,Math.min(100,Number(range.value)||0));if(out)out.value=String(n)});range?.addEventListener('change',async()=>{const n=Math.max(0,Math.min(100,Number(range.value)||0));try{if(window.jfmSpotifyPlayer?.setVolume)await window.jfmSpotifyPlayer.setVolume(n/100)}catch{}})}}
function sync(){const node=overlay();if(!node)return false;ensureExtras();const shouldApply=enabled&&media.matches;node.classList.toggle('mair-sleep-landscape-v2',shouldApply);node.dataset.sleepLayout=shouldApply?'landscape-bedside':'default';lastApplied=shouldApply;const art=$('mairSleepLandscapeArt');if(art)art.src=artworkSrc();try{window.dispatchEvent(new CustomEvent('mair:sleep-layout',{detail:{layout:node.dataset.sleepLayout,active:shouldApply}}))}catch{}return shouldApply}
function setEnabled(value){enabled=!!value;sync();return status()}
function status(){return{version:'landscape-bedside-2026-08-29c',enabled,matches:media.matches,applied:lastApplied,sleepAvailable:!!window.MAIRSleep,overlayAvailable:!!overlay()}}
function boot(){sync();media.addEventListener?.('change',sync);window.addEventListener('resize',sync,{passive:true});window.addEventListener('orientationchange',()=>setTimeout(sync,80),{passive:true});['mair:sleep','mair:foundation-ready','jfm:trackchange','jfm:playback-state'].forEach(n=>window.addEventListener(n,sync));const observer=new MutationObserver(()=>{if(overlay()){sync();observer.disconnect()}});if(!overlay())observer.observe(document.documentElement,{childList:true,subtree:true});setTimeout(sync,250);setTimeout(sync,1200)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
window.MAIRSleepLandscapePrototype={version:'landscape-bedside-2026-08-29c',enable:()=>setEnabled(true),disable:()=>setEnabled(false),sync,status};
})();
